async function load(){if(documents)return documents;const paths=['afluencia-resumen.json','locales.json','catalogo-planos.json'];const result=await Promise.all(paths.map(async p=>{const r=await fetch('documentacion/'+p+'?v=81');if(!r.ok)throw Error(p);return r.json();}));documents={demand:result[0],locals:result[1],plans:result[2]};return documents;}
function render(){const {demand,locals}=documents;
 $('documents-content').innerHTML=`<section><h3>Revisión 150 · Mantenimiento instalado</h3><p>Seis prácticas sobre equipos montados en sus gabinetes, tableros diferenciados por función y portada sin cobertura de carga.</p><a href="docs/Referencias150.html" target="_blank" rel="noopener">Montaje, tableros y verificaciones</a></section><section><h3>Revisión 149 · Conducción con manos</h3><p>Palanca 3D de tracción y freno, manos articuladas y pulsadores directos. Velocidad y puertas en el pupitre.</p><a href="docs/Referencias149.html" target="_blank" rel="noopener">Controles, modelos y verificaciones</a></section><section><h3>Revisión 148 · Mantenimiento y equipos</h3><p>Caída de tensión bajo carga, aislamiento con tendencia y descarga, S1 auxiliar, inspección de rueda y secuencia cruzada. Once modelos Blender revisados.</p><a href="docs/Referencias148.html" target="_blank" rel="noopener">Renders, actividades, fuentes y verificaciones</a></section><section><h3>Revisión 147 · Vagones y navegación</h3><p>Asientos de Línea 8 reemplazados, seis plantillas actualizadas, nuevos pupitres y velocidad en cabina. Portada, actividades y cámaras reorganizadas.</p><a href="docs/Referencias147.html" target="_blank" rel="noopener">Renders, referencias, cambios y límites</a></section><section><h3>Revisión 146 · Referencias de subestaciones</h3><p>Dos PDF y tres videos contrastados. Instrumentación de aguja, botoneras y detalle mecánico; interpretación de evidencia y bitácora exportable en las seis prácticas.</p><a href="docs/Referencias146.html" target="_blank" rel="noopener">Análisis, fuentes, cambios y límites</a></section><section><h3>Revisión 145 · Carga y taller de subestación</h3><p>Compatibilidad con el catálogo anterior de pasajeros, recuperación de carga, siete modelos Blender refinados y uso visible de herramientas en las seis prácticas de subestación.</p><a href="docs/Revision145.md" target="_blank" rel="noopener">Cambios y verificaciones</a></section><section><h3>Integración 144 · ampliaciones del ZIP</h3><p>Portal técnico, guía de piezas, pasajeros con texturas, ajuste asistido de parada, mapa L8 y despiece gradual de subestación. Se conservan los documentos y las correcciones recientes de mantenimiento.</p><a href="docs/Integracion144.md" target="_blank" rel="noopener">Evaluación y verificaciones</a> · <a href="documentacion/personajes144-creditos.json" target="_blank" rel="noopener">Créditos de personajes</a> · <a href="documentacion/integracion144.json" download>Inventario de comparación</a></section><section><h3>Revisión 117 · Taller de juego</h3><p>Mano sobre las piezas, retícula de exploración, agarres por herramienta y órdenes de trabajo. Banco a pantalla completa con objetivos, barra de herramientas y resultados de misión.</p><a href="docs/Revision117.md" target="_blank" rel="noopener">Cambios, controles y verificaciones</a></section><section><h3>Revisión 116 · Interacción y movimiento</h3><p>Gestos de mantenimiento más estables, herramientas detalladas, LCD del multímetro conectado a la misión y movimientos graduales. Pasajeros con transición caminar/reposo e identidades estables.</p><a href="docs/Revision116.md" target="_blank" rel="noopener">Cambios y pruebas</a></section><section><h3>Revisión 115 · Materiales y coherencia visual</h3><p>Revisión de todos los GLB: ropa, piel, cabello, calzado, piedra, metales, difusores y guante definitivo. Texturas y paletas conservadas; acabados e iluminación de reflejos ajustados.</p><a href="docs/Revision115.md" target="_blank" rel="noopener">Alcance y pruebas</a> · <a href="documentacion/auditoria-realismo115.json" target="_blank" rel="noopener">Auditoría de modelos</a></section><section><h3>Revisión 114 · Portada de juego</h3><p>Cuatro modos con tarjetas, guía de tres pasos y acceso directo. Selección con cursor o teclado y progreso de taller conservado.</p><a href="docs/Revision114.md" target="_blank" rel="noopener">Cambios y verificaciones</a></section><section><h3>Revisión 113 · Interior de Línea 8</h3><p>Ventanillas de testero altas y redondeadas, rejillas ajustadas, uniones y bases de pasamanos y remates de puertas. Acabados de techo y asientos revisados desde fotografías.</p><a href="docs/Revision113.md" target="_blank" rel="noopener">Correcciones y verificaciones</a></section><section><h3>Revisión 112 · Bogies según referencia completa</h3><p>Protecciones abiertas alrededor de los captadores y ruedas guía horizontales con sus soportes. Las seis plantillas GLB se actualizaron con dimensiones aproximadas desde las fotografías.</p><a href="docs/Revision112.md" target="_blank" rel="noopener">Cambios y alcance</a></section><section><h3>Revisión 111 · Captación de corriente</h3><p>Captadores positivos integrados en los bogies de coches motrices de los tres modelos. Soportes, aisladores, patines y conexiones aproximados; sección de inspección y despiece en el taller.</p><a href="docs/Revision111.md" target="_blank" rel="noopener">Alcance y fuentes</a> · <a href="models/Captador_positivo111.glb.gz" download>Captador GLB comprimido</a></section><section><h3>Revisión 110 · Materiales de los modelos</h3><p>Pintura esmaltada, acero cepillado, pasamanos pulidos, paneles, asientos y caucho diferenciados; cristales y microtexturas refinados. Colores y mapas originales conservados.</p><a href="docs/Revision110.md" target="_blank" rel="noopener">Alcance y verificaciones</a></section><section><h3>Revisión 109 · Corte automático por cámara</h3><p>Andén fijo muestra el entorno completo; Seguir tren activa los cortes de túnel y estación automáticamente.</p><a href="docs/Revision109.md" target="_blank" rel="noopener">Cambios y comprobaciones</a></section><section><h3>Revisión 108 · Cortes en seguimiento</h3><p>Cortes de túnel y andén activos al iniciar seguimiento, con controles visibles. El lado del corte se adapta a la orientación del trazado.</p><a href="docs/Revision108.md" target="_blank" rel="noopener">Cambios y verificaciones</a></section><section><h3>Revisión 107 · Puesto de conducción</h3><p>Consola fuera del escenario, vistas directas frontal y al andén, mensajes del operador visibles y Cortar andén accesible en seguimiento.</p><a href="docs/Revision107.md" target="_blank" rel="noopener">Cambios y comprobaciones</a></section><section><h3>Revisión 106 · Conducción y seguimiento</h3><p>Escena a pantalla completa, mandos inferiores, cámaras y mapa desplegables. Opciones secundarias retiradas de estas vistas.</p><a href="docs/Revision106.md" target="_blank" rel="noopener">Cambios y verificaciones</a></section><section><h3>Revisión 105 · Metro / Operaciones</h3><p>Nueva interfaz de juego en todas las áreas, pausa y ajustes funcionales, HUD compacto y mandos junto a la vista de conducción. Reflejos, iluminación y sombras de contacto refinados.</p><a href="docs/Revision105.md" target="_blank">Cambios, perfiles y verificaciones</a></section><section><h3>Revisión 104 · fluidez y guante continuo</h3><p>Movimientos de piezas interpolados, manipulación durante el arrastre, guante GLB articulado de Blender y bancos con más detalle. El mantenimiento admite hasta 60 Hz con resolución adaptable.</p><a href="docs/Revision104.md" target="_blank">Cambios, modelos y comprobaciones</a></section><section><h3>Revisión 103 · GLB y lluvia</h3><p>Un solo indicador en el banco, selección de piezas corregida y cuatro bancos exportados con Blender. Clima y marcha lluvia configurables en conducción y simulación.</p><a href="docs/Revision103.md" target="_blank">Cambios, archivos GLB y verificaciones</a></section><section><h3>Revisión 102 · nuevo banco de mantenimiento</h3><p>Cuatro prácticas con una nueva interfaz, mecanismos 3D, guante articulado y acciones directas con el mouse. Manual de la misión, destinos de piezas y comprobaciones visibles.</p><a href="docs/Revision102.md" target="_blank" rel="noopener">Cambios y comprobaciones</a></section><section><h3>Revisión 101 · rendimiento</h3><p>Menos cálculos de huesos y objetos estáticos; render de hasta 30 Hz y resolución adaptable. Se conservan modelos, texturas, pasajeros y reloj de simulación.</p><a href="docs/Revision101.md" target="_blank" rel="noopener">Cambios y medición de CPU</a></section><section><h3>Revisión 100 · interiores y calidad visual</h3><p>NM-79 y MP-82: retiradas las manijas anteriores, bisagras corregidas y testeros cerrados en su remate superior. Materiales PBR y reflejos refinados en trenes, estaciones, taller y menú; luces locales en cabina e interior.</p><a href="docs/Revision100.md" target="_blank" rel="noopener">Cambios, comprobaciones y límites</a></section><section><h3>Revisión 99 · vías y locales de Línea 8</h3><p>Vías neumáticas con pistas, barras guía, rieles de seguridad y fijaciones. Carteles No pase y señales luminosas al final de los andenes. Línea 8 incorpora 19 locales eléctricos ilustrativos, cinco junto al exterior de estaciones de superficie; no representan un inventario oficial.</p><a href="docs/Revision99.md" target="_blank" rel="noopener">Alcance, referencias y comprobaciones</a></section><section><h3>Revisión 97 · trazados, túneles y señalización</h3><p>Vías y convoyes siguen curvas derivadas de los ejes CAD aportados. Los andenes permanecen rectos y las cámaras siguen el mismo trazado. Los radios de enlace son aproximados, no un levantamiento topográfico.</p><p>Pantallas de llegadas separadas de los carteles exclusivos en las 39 estaciones. Separadores fijos rosa/blanco en Línea 1 y verde/blanco en Línea 8, sin barreras anteriores activas.</p><a href="docs/Revision97.md" target="_blank" rel="noopener">Revisión, fuentes y límites</a></section><section><h3>Subestaciones y motores · revisión 94</h3><p>40 locales SAF ilustrativos en Línea 1. El inventario del STC respalda 40 subestaciones de alumbrado y fuerza en 20 estaciones; las posiciones en túnel y la geometría son aproximadas. No son 40 rectificadoras. Desde la revisión 99, Línea 8 incluye locales ilustrativos; su inventario real sigue sin confirmar.</p><p><a href="docs/Revision94.md" target="_blank">Alcance y referencias</a> · <a href="documentacion/estudio89/prescripciones-2020.pdf#page=114" target="_blank">Especificaciones de motores · página 114</a></p><p>Despieces: colector y escobillas como referencia visual para NM-79/MP-82; jaula de ardilla como requisito del proyecto de Línea 1, no verificación del motor construido del NM-22. <a href="models/Motor_NM22_referencia94.glb.gz" download>Motor L1</a> · <a href="models/Motor_NM79_referencia94.glb.gz" download>Motor NM-79</a> · <a href="models/Motor_MP82_referencia94.glb.gz" download>Motor MP-82</a> (GLB comprimidos, descomprimir .gz).</p></section><section><h3>Revisión 93 · clic y separadores fijos</h3><p>Las cuatro misiones aceptan clic sobre piezas o botones con nombre; cada clic en una fijación gira ¼ de vuelta. Línea 8 incorpora paneles blancos con vidrio superior, detalles verdes, cartel y paso central de 1,50 m. Adaptación visual de las referencias de Línea 1, con ubicación y medidas aproximadas.</p><p><a href="docs/Revision93.md" target="_blank" rel="noopener">Controles y comprobaciones</a> · <a href="models/Separador_fijo_Linea8.glb.gz" download>Descargar separador GLB</a></p></section><section><h3>Revisión 92 · misiones y cerraduras de Línea 8</h3><p>Nueva interfaz, correcciones del banco de mantenimiento, asignación de pasajeros y cerraduras de testeros según tus fotografías. <a href="docs/Revision92.md" target="_blank" rel="noopener">Ver cambios, comprobaciones y alcance</a>.</p><p><a href="models/Cerradura_testero_L8.glb" download>Descargar cerradura GLB</a> · <a href="referencias/cerradura92/01-39261.jpg" target="_blank" rel="noopener">Fotografía de referencia</a></p></section><section><h3>Zona exclusiva del andén · referencia fotográfica 91</h3><p>Barrera naranja con asas, apoyos y cartel rosa según las fotografías aportadas. Desde la revisión 97, ambas líneas utilizan separadores fijos: blanco y rosa en Línea 1, blanco y verde en Línea 8. Las barreras naranjas previas se retiraron de las escenas. Las posiciones son aproximadas. La configuración de tres coches delanteros es de referencia; no acredita la ubicación real de cada separación.</p><p><a href="models/Separador_fijo_Linea1.glb.gz" download>Descargar separador fijo de Línea 1 · GLB comprimido</a> · <a href="docs/Zona_exclusiva91.md" target="_blank" rel="noopener">Alcance y fuentes</a></p><div class="document-file-grid">${['01-39245.jpg','02-39244.jpg','03-39243.jpg'].map(file=>`<a href="referencias/zona91/${file}" target="_blank" rel="noopener"><img src="referencias/zona91/${file}" loading="lazy" alt="Referencia aportada de barrera naranja y cartel rosa" style="width:100%;max-width:250px"></a>`).join('')}</div></section><section><h3>Demanda documentada de pasajeros</h3><p>Las bases llegan al <b>31 de julio de 2026</b>. El nuevo modo <b>CSV reciente · por estación y día</b> usa la media de mayo–julio de 2026 y permite elegir día de la semana. El perfil horario del Excel se normaliza para conservar el total diario; donde falta perfil, se estima un reparto uniforme de 05:00 a 23:00.</p><p>Son entradas a la estación, no conteos de espera, transbordos ni ocupación del tren. El comportamiento de embarque y los destinos siguen siendo simulados. No se suman las dos bases.</p><p><b>${demand.matchedRows.toLocaleString('es-MX')}</b> claves comparables de L1/L8 verificadas, sin diferencias al sumar Boleto, Prepago y Gratuidad.</p><a href="documentacion/afluencia-resumen.json" download>Descargar datos compactos y trazabilidad</a></section>
 <section><h3>Locales técnicos por estación · Línea 1</h3><p>Consulta la lámina para contrastar andenes, vestíbulos y conexiones con las referencias fotográficas. Las zonas sombreadas indican <b>opciones de local técnico</b>; no son accesos de pasajeros. Merced y Pantitlán muestran el nivel vestíbulo: no permiten deducir toda la planta del andén. Medidas, acabados y cambios posteriores requieren otras referencias.</p><label>Estación <select id="document-station">${locals.map(x=>`<option value="${escape(x.stationId)}">${escape(x.name)}</option>`).join('')}</select></label><p id="document-local-caption"></p><a id="document-local-pdf" target="_blank" rel="noopener">Abrir página en PDF</a><div class="document-plan"><img id="document-local-image" alt="Lámina de locales técnicos" loading="lazy"></div></section>
 <section><h3>Conducción y fallas · requisitos CBTC de Línea 1</h3><ul><li>Velocidad y autorización de movimiento: §§ 9.12–9.19.</li><li>Control de la marcha y parada: § 10.</li><li>Supervisión de apertura y cierre: § 11.6.1. Se impide la salida con puertas abiertas.</li><li>Pérdida de supervisión de puertas: § 11.8.8, páginas 72–73. Detenido: inmovilización; en marcha: freno de servicio y alarma.</li><li>Modos degradados: § 12. Referencia para desarrollar ejercicios; no se implementan todos los modos reales.</li></ul><p>La advertencia de cierre de 5 segundos conserva la elección previa del simulador; este PDF no acredita ese tiempo como ajuste real del tren. No se atribuye el CBTC de Línea 1 a Línea 8.</p><div class="document-fault"><h4>Ensayo de supervisión de puertas</h4><p>Entra en <b>Conducir el Metro</b> con NM-22. Simula la pérdida de la confirmación de bloqueo y observa el freno y la inhibición de tracción. Restablece la señal con el tren detenido y vuelve a aplicar tracción.</p><button id="document-fault-toggle">Simular pérdida de bloqueo</button><p id="document-fault-status" role="status"></p></div></section>
 <section><h3>Catálogo de planos de vías · 93 entradas</h3><p>El Excel es un índice. Los enlaces siguientes llevan a las copias del paquete técnico que ya estaban integradas, cuando existe una asociación. Los kilometrajes históricos y los planos no certifican la geometría actual.</p><label>Buscar código o descripción <input id="document-plan-search" type="search" placeholder="peralte, Zaragoza, TV…"></label><p id="document-plan-count" role="status"></p><div id="document-plan-list"></div></section>
 <section><h3>Instalaciones y mantenimiento: anexos por consultar</h3><p>La nota del 30 de julio de 2020 modifica alcances de cableado de tracción, alumbrado de interestaciones, tierras, puentes de continuidad, aire acondicionado, cárcamos y drenaje del túnel. También agrega información del NM-16. Debemos consultar los anexos modificados antes de reproducir valores o conexiones.</p><p>El banco eléctrico de 24 V sigue siendo un ejercicio didáctico. Estos documentos no aportan un circuito de mantenimiento específico del MP-82 o NM-79 para sustituirlo.</p></section>
 <section><h3>Referencias de vía fija · consulta ampliada</h3><p>Dos paquetes aportados: <b>217 PDF distintos y 1,503 páginas</b>, clasificados en 183 fichas o piezas y 34 especificaciones técnicas. Dos Excel enumeran especificaciones y fichas de inspección. Se inventarió todo el paquete y se extrajo texto u OCR de sus 1,503 páginas. La consulta con búsqueda está disponible en Qué está integrado. Esto no equivale a validar cada dibujo o cota.</p><p>Útiles para rieles, pistas de rodamiento, aisladores, fijaciones, juntas y aparatos de vía. No son manuales completos de reparación de los trenes. Algunas especificaciones corresponden a Línea B y las fichas contienen fechas históricas: hay que comprobar su aplicación a L1/L8. También falta comprobar la integridad de los escaneos.</p><a href="documentacion/catalogo-vias84.json" download>Descargar inventario y alcance de revisión</a><p>Los PDF originales permanecen en los ZIP aportados; el lector incorpora sus textos, no las láminas originales ni sus cotas al modelo 3D.</p></section><section><h3>Los ocho documentos originales</h3><div class="document-file-grid">${files.map(([file,title,scope])=>`<article><b>${escape(title)}</b><p>${escape(scope)}</p><a href="documentacion/${file}" ${/pdf$/.test(file)?'target="_blank" rel="noopener"':'download'}>${/pdf$/.test(file)?'Abrir PDF':'Descargar archivo'}</a></article>`).join('')}</div><p>Los originales se conservan íntegros. Las correcciones de nombres y codificación se aplican únicamente a los datos preparados para el simulador. <a href="documentacion/fuentes.json" download>Registro de archivos y huellas SHA-256</a>.</p></section>`;
 const state=window.metroViewState?.();const context=state?.currentLine===1?state.selectedStation:null;if(locals.some(x=>x.stationId===context))$('document-station').value=context;
 $('document-station').onchange=showLocal;showLocal();$('document-plan-search').oninput=showPlans;showPlans();$('document-fault-toggle').onclick=toggleFault;faultStatus();mountKnowledge89($('documents-content'));info144=mountInfoShell139($('documents-content'),()=>{ $('guide-fault-toggle144').onclick=toggleFault;faultStatus();});info144.showPortal();
}
function showLocal(){const item=documents.locals.find(x=>x.stationId===$('document-station').value);if(!item)return;$('document-local-image').src=item.preview;$('document-local-image').alt='Propuesta de locales técnicos de '+item.name+', marzo 2020';$('document-local-caption').textContent=item.name+' · página '+item.page+' de 21 · propuesta de marzo 2020';$('document-local-pdf').href='documentacion/boletin-locales-tecnicos.pdf#page='+item.page;}
const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function showPlans(){const q=norm($('document-plan-search').value),items=documents.plans.filter(x=>norm(x.code+' '+x.description).includes(q));$('document-plan-count').textContent=items.length+' entradas';$('document-plan-list').innerHTML=items.map(x=>`<article><b>${x.number}. ${escape(x.code)}</b><p>${escape(x.description)}</p>${x.pdf?`<a href="${escape(x.pdf)}" target="_blank" rel="noopener">Consultar copia del plano</a>`:'<small>Sin copia asociada inequívocamente; consultar el índice.</small>'}</article>`).join('');}
function faultStatus(){updateFault144('document-fault-toggle','document-fault-status');updateFault144('guide-fault-toggle144','guide-fault-status144');}
function updateFault144(buttonId,statusId){const state=window.metroViewState?.(),op=state?.engine.operator,t=state?.engine.trains.find(t=>t.id===op?.trainId),valid=t?.line===1&&document.body.dataset.driving==='true';const button=$(buttonId);if(!button)return;button.disabled=!valid||(op.doorFault&&t.speed>.08);button.textContent=op?.doorFault?'Restablecer confirmación de bloqueo':'Simular pérdida de bloqueo';$(statusId).textContent=!valid?'Disponible al conducir el NM-22 de Línea 1.':op.doorFault?t.speed>.08?'Falla activa: freno de servicio. Espera a que el tren se detenga para restablecer.':'Falla activa: tren detenido, tracción bloqueada.':'Sin falla inducida. Señal de puertas: '+(op.phase==='closed'?'cerradas y bloqueadas':'ciclo de apertura/cierre');}
function toggleFault(){const state=window.metroViewState?.(),op=state?.engine.operator,t=state?.engine.trains.find(t=>t.id===op?.trainId);if(!op||t?.line!==1||document.body.dataset.driving!=='true'||op.doorFault&&t.speed>.08)return;op.doorFault=!op.doorFault;op.doorsLocked=!op.doorFault&&op.phase==='closed';op.throttle=0;op.brake=1;op.assisted=false;op.message=op.doorFault?'Falla simulada: pérdida de bloqueo de puertas. Tracción inhibida y freno de servicio.':'Confirmación restablecida. Freno mantenido; aplica tracción para salir.';faultStatus();}
$('documents-open').onclick=async()=>{$('documents-dialog').showModal();try{await load();render();$('documents-status').textContent='Portal técnico · partes y cálculos · documentos y fuentes originales';}catch(e){$('documents-status').textContent='No se pudo cargar la documentación. Cierra y vuelve a abrir para reintentar.';}};
$('documents-close').onclick=()=>$('documents-dialog').close();
setInterval(()=>{if($('documents-dialog').open)faultStatus();},500);
document.addEventListener('metro-study-open',e=>{setStudyRequest89(e.detail);$('documents-open').click();});
document.addEventListener('click',async event=>{const a=event.target.closest?.('a[download]'),path=a&&compressedDownloadPath(a.getAttribute('href')||'');if(!path)return;event.preventDefault();const old=a.textContent;a.textContent='Preparando GLB…';try{const r=await fetch(path);if(!r.ok)throw Error('Modelo no disponible');const blob=await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).blob();const link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download=path.split('/').at(-1).replace(/\.gz$/,'');link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}catch{const link=document.createElement('a');link.href=path;link.download=path.split('/').at(-1);link.click();}finally{a.textContent=old;}});

document.addEventListener('metro-info-open',async e=>{await $('documents-open').onclick();info144?.open(e.detail?.part);});
